import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './login-page.css';
import Header from '../../components/Header/Header';
import Footer from '../../components/Footer/Footer';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [userType, setUserType] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    if (!email.trim() || !password.trim() || !userType.trim()) {
      alert('Please fill in all fields.');
      return;
    }

    setIsSubmitting(true);
    const payload = { email, password, userType };
    try {
      const response = await fetch('http://localhost:5000/login_user', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (response.status === 200) {
        alert('Login successful!');
        localStorage.setItem('userEmail', email);
        navigate(userType === 'admin' ? '/admin' : '/dashboard');
      }
    } catch (error) {
      alert('An error occurred. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="login-page">
      <Header />
      <div className="login-container">
        <div className="left-section">
          <img src="/images/mock-interview.jpg" alt="Mock Interview" className="left-image" />
          <h2 className="image-title">Mock Interview</h2>
        </div>
        <div className="form-section">
          <h2>Login</h2>
          <form onSubmit={handleLogin} className="login-form">
            <div className="form-group">
              <label htmlFor="email">Email</label>
              <input type="email" id="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
            </div>
            <div className="form-group">
              <label htmlFor="password">Password</label>
              <input type="password" id="password" value={password} onChange={(e) => setPassword(e.target.value)} required />
            </div>
            <div className="form-group radio-buttons">
              <label>User Type</label>
              <div className="radio-options">
                <label><input type="radio" value="admin" checked={userType === 'admin'} onChange={(e) => setUserType(e.target.value)} />Admin</label>
                <label><input type="radio" value="student" checked={userType === 'student'} onChange={(e) => setUserType(e.target.value)} />Student</label>
              </div>
            </div>
            <button type="submit" disabled={isSubmitting} className="login-button">{isSubmitting ? 'Logging in...' : 'Login'}</button>
            <button type="button" onClick={() => navigate('/sign-up')} className="signup-button">Sign Up</button>
          </form>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default LoginPage;
